-- Local design prototype, version 1. Surrogate IDs are fixture-local, not EMMA keys.
CREATE TABLE source_document (document_id INTEGER PRIMARY KEY, title VARCHAR NOT NULL, document_type VARCHAR);
CREATE TABLE source_version (source_version_id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES source_document(document_id), version_label VARCHAR, sha256 VARCHAR NOT NULL, source_uri VARCHAR, UNIQUE(document_id, sha256));
CREATE TABLE source_passage (passage_id INTEGER PRIMARY KEY, source_version_id INTEGER NOT NULL REFERENCES source_version(source_version_id), locator VARCHAR NOT NULL, extracted_text VARCHAR);
CREATE TABLE external_system (system_id INTEGER PRIMARY KEY, system_name VARCHAR NOT NULL UNIQUE);
CREATE TABLE external_reference (external_ref_id INTEGER PRIMARY KEY, system_id INTEGER NOT NULL REFERENCES external_system(system_id), entity_kind VARCHAR NOT NULL, namespace VARCHAR NOT NULL, native_id VARCHAR NOT NULL, UNIQUE(system_id, namespace, entity_kind, native_id));
CREATE TABLE research_question (question_id INTEGER PRIMARY KEY, question_text VARCHAR NOT NULL, origin_kind VARCHAR NOT NULL, source_passage_id INTEGER REFERENCES source_passage(passage_id), record_status VARCHAR NOT NULL);
CREATE TABLE hypothesis (hypothesis_id INTEGER PRIMARY KEY, hypothesis_text VARCHAR NOT NULL, origin_kind VARCHAR NOT NULL, source_passage_id INTEGER REFERENCES source_passage(passage_id), record_status VARCHAR NOT NULL);
CREATE TABLE study (study_id INTEGER PRIMARY KEY);
CREATE TABLE study_version (study_version_id INTEGER PRIMARY KEY, study_id INTEGER NOT NULL REFERENCES study(study_id), version_no INTEGER NOT NULL, title VARCHAR NOT NULL, description VARCHAR, UNIQUE(study_id, version_no));
CREATE TABLE study_event (event_id INTEGER PRIMARY KEY, study_version_id INTEGER REFERENCES study_version(study_version_id), description VARCHAR NOT NULL, start_date DATE, end_date DATE, date_precision VARCHAR, source_passage_id INTEGER REFERENCES source_passage(passage_id), CHECK (start_date IS NULL OR end_date IS NULL OR start_date <= end_date));
CREATE TABLE question_hypothesis (link_id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL REFERENCES research_question(question_id), hypothesis_id INTEGER NOT NULL REFERENCES hypothesis(hypothesis_id), relation_type VARCHAR NOT NULL, source_passage_id INTEGER REFERENCES source_passage(passage_id), attribution VARCHAR, record_status VARCHAR NOT NULL, scope_note VARCHAR);
CREATE TABLE question_study (link_id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL REFERENCES research_question(question_id), study_id INTEGER NOT NULL REFERENCES study(study_id), relation_type VARCHAR NOT NULL, source_passage_id INTEGER REFERENCES source_passage(passage_id), attribution VARCHAR, record_status VARCHAR NOT NULL, scope_note VARCHAR);
CREATE TABLE hypothesis_study (link_id INTEGER PRIMARY KEY, hypothesis_id INTEGER NOT NULL REFERENCES hypothesis(hypothesis_id), study_id INTEGER NOT NULL REFERENCES study(study_id), relation_type VARCHAR NOT NULL, source_passage_id INTEGER REFERENCES source_passage(passage_id), attribution VARCHAR, record_status VARCHAR NOT NULL, scope_note VARCHAR);
CREATE TABLE project_objective (objective_id INTEGER PRIMARY KEY, objective_text VARCHAR NOT NULL, project_ref_id INTEGER REFERENCES external_reference(external_ref_id), emma_objective_ref_id INTEGER REFERENCES external_reference(external_ref_id), source_passage_id INTEGER REFERENCES source_passage(passage_id), record_status VARCHAR NOT NULL);
CREATE TABLE performance_criterion (criterion_id INTEGER PRIMARY KEY, criterion_text VARCHAR NOT NULL, target_date DATE, emma_criterion_ref_id INTEGER REFERENCES external_reference(external_ref_id), source_passage_id INTEGER REFERENCES source_passage(passage_id), record_status VARCHAR NOT NULL);
CREATE TABLE objective_criterion (objective_id INTEGER NOT NULL REFERENCES project_objective(objective_id), criterion_id INTEGER NOT NULL REFERENCES performance_criterion(criterion_id), source_passage_id INTEGER REFERENCES source_passage(passage_id), note VARCHAR, PRIMARY KEY(objective_id, criterion_id));
CREATE TABLE monitoring_task_ref (monitoring_task_ref_id INTEGER PRIMARY KEY, external_ref_id INTEGER NOT NULL REFERENCES external_reference(external_ref_id));
CREATE TABLE task_criterion (monitoring_task_ref_id INTEGER NOT NULL REFERENCES monitoring_task_ref(monitoring_task_ref_id), criterion_id INTEGER NOT NULL REFERENCES performance_criterion(criterion_id), source_passage_id INTEGER REFERENCES source_passage(passage_id), note VARCHAR, PRIMARY KEY(monitoring_task_ref_id, criterion_id));
CREATE TABLE finding (finding_id INTEGER PRIMARY KEY);
CREATE TABLE finding_version (finding_version_id INTEGER PRIMARY KEY, finding_id INTEGER NOT NULL REFERENCES finding(finding_id), version_no INTEGER NOT NULL, study_version_id INTEGER REFERENCES study_version(study_version_id), finding_text VARCHAR NOT NULL, finding_type VARCHAR NOT NULL, authorship_status VARCHAR NOT NULL, created_at TIMESTAMP NOT NULL, UNIQUE(finding_id, version_no));
CREATE TABLE finding_passage (finding_version_id INTEGER NOT NULL REFERENCES finding_version(finding_version_id), passage_id INTEGER NOT NULL REFERENCES source_passage(passage_id), evidence_role VARCHAR NOT NULL, rationale VARCHAR, PRIMARY KEY(finding_version_id, passage_id, evidence_role));
CREATE TABLE assessment (assessment_id INTEGER PRIMARY KEY, assessment_text VARCHAR NOT NULL, assessment_type VARCHAR NOT NULL, assessment_date DATE, source_passage_id INTEGER REFERENCES source_passage(passage_id), authorship VARCHAR, record_status VARCHAR NOT NULL);
CREATE TABLE assessment_finding (assessment_id INTEGER NOT NULL REFERENCES assessment(assessment_id), finding_version_id INTEGER NOT NULL REFERENCES finding_version(finding_version_id), role VARCHAR, rationale VARCHAR, source_passage_id INTEGER REFERENCES source_passage(passage_id), PRIMARY KEY(assessment_id, finding_version_id));
CREATE TABLE assessment_criterion (assessment_id INTEGER NOT NULL REFERENCES assessment(assessment_id), criterion_id INTEGER NOT NULL REFERENCES performance_criterion(criterion_id), role VARCHAR, rationale VARCHAR, source_passage_id INTEGER REFERENCES source_passage(passage_id), PRIMARY KEY(assessment_id, criterion_id));
CREATE TABLE assessment_objective (assessment_id INTEGER NOT NULL REFERENCES assessment(assessment_id), objective_id INTEGER NOT NULL REFERENCES project_objective(objective_id), role VARCHAR, rationale VARCHAR, source_passage_id INTEGER REFERENCES source_passage(passage_id), PRIMARY KEY(assessment_id, objective_id));
CREATE TABLE decision (decision_id INTEGER PRIMARY KEY, decision_text VARCHAR NOT NULL, decision_type VARCHAR NOT NULL, decision_date DATE, decision_maker VARCHAR, source_passage_id INTEGER REFERENCES source_passage(passage_id), record_status VARCHAR NOT NULL);
CREATE TABLE assessment_decision (assessment_id INTEGER NOT NULL REFERENCES assessment(assessment_id), decision_id INTEGER NOT NULL REFERENCES decision(decision_id), rationale VARCHAR, source_passage_id INTEGER REFERENCES source_passage(passage_id), PRIMARY KEY(assessment_id, decision_id));
CREATE TABLE decision_action (action_id INTEGER PRIMARY KEY, decision_id INTEGER NOT NULL REFERENCES decision(decision_id), action_text VARCHAR NOT NULL, action_status VARCHAR, source_passage_id INTEGER REFERENCES source_passage(passage_id));
CREATE TABLE study_external_link (link_id INTEGER PRIMARY KEY, study_id INTEGER NOT NULL REFERENCES study(study_id), external_ref_id INTEGER NOT NULL REFERENCES external_reference(external_ref_id), relationship_type VARCHAR NOT NULL, scope_note VARCHAR, valid_from DATE, valid_to DATE, review_state VARCHAR NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE study_link_passage (link_id INTEGER NOT NULL REFERENCES study_external_link(link_id), passage_id INTEGER NOT NULL REFERENCES source_passage(passage_id), role VARCHAR NOT NULL, PRIMARY KEY(link_id, passage_id, role));
CREATE VIEW question_finding_path AS SELECT q.question_id, q.question_text, qs.relation_type, qs.record_status AS relation_status, qs.scope_note, sv.title AS study_title, fv.finding_text, fv.authorship_status, sd.title AS source_title, sp.locator AS source_locator, src.sha256 AS source_sha256 FROM research_question q JOIN question_study qs ON qs.question_id = q.question_id JOIN study_version sv ON sv.study_id = qs.study_id JOIN finding_version fv ON fv.study_version_id = sv.study_version_id JOIN finding_passage fp ON fp.finding_version_id = fv.finding_version_id JOIN source_passage sp ON sp.passage_id = fp.passage_id JOIN source_version src ON src.source_version_id = sp.source_version_id JOIN source_document sd ON sd.document_id = src.document_id;
CREATE VIEW objective_criterion_path AS SELECT o.objective_id, o.objective_text, o.record_status AS objective_status, c.criterion_id, c.criterion_text, c.record_status AS criterion_status, oc.note, sp.locator AS source_locator FROM project_objective o JOIN objective_criterion oc ON oc.objective_id = o.objective_id JOIN performance_criterion c ON c.criterion_id = oc.criterion_id LEFT JOIN source_passage sp ON sp.passage_id = oc.source_passage_id;
